9: import { approveSection, reviseSection, WorkflowConflict } from "./workflow/transitions.ts";
10: 
11: export type EngineProbe = () => Promise<NativeEngineStatus>;
12: 
13: const actionSchema = z.object({
14:   actionId: z.string().min(1),
15:   expectedRevision: z.number().int().nonnegative(),
16: });
17: const revisionSchema = actionSchema.extend({ content: z.string().min(1).max(65_536) });
18: const approvalRequestSchema = actionSchema.extend({
19:   version: z.number().int().positive(),
20:   hash: z.string().length(64),
21: });
22: 
23: const messageSchema = actionSchema.extend({
24:   intent: z.enum(["clarify", "draft", "question", "witness"]),
25:   text: z.string().min(1).max(8_000),
26: });
27: const approvalKindSchema = z.discriminatedUnion("kind", [
28:   actionSchema.extend({ kind: z.literal("product") }),
29:   actionSchema.extend({ kind: z.literal("maker-scope"), statement: z.string().min(8).max(2_000) }),
30: ]);
31: 
32: export interface WorkflowHttpOptions {
33:   service: WorkflowService;
34:   sessionToken: string;
35:   experience?: ExperienceService;
36:   access?: {
37:     username: string;
38:     password: string;
39:   };
40: }
41: 
42: export function createApp(probe: EngineProbe, workflow?: WorkflowHttpOptions) {
43:   const app = new Hono();
44: 
45:   app.use(sentry(app));
46: 
47:   if (workflow?.access) {
48:     const authenticate = basicAuth({
49:       username: workflow.access.username,
50:       password: workflow.access.password,
51:       realm: "Unfinished Business",
52:     });
53:     app.use("*", async (context, next) => {
54:       if (context.req.path === "/api/health") return next();
55:       return authenticate(context, next);
56:     });
57:   }
58: 
59:   app.get("/api/health", (context) => context.json(healthSchema.parse({
60:     status: "ok",
61:     service: "unfinished-business",
62:   })));
63: 
64:   app.get("/api/engine", async (context) => {
65:     const status = nativeEngineStatusSchema.parse(await probe());
66:     return context.json(status, status.available ? 200 : 503);
67:   });
68: 
69:   if (workflow) {
70:     app.get("/api/project", async (context) => context.json(await workflow.service.get()));
71:     app.get("/api/session", (context) => {
72:       if (workflow.access) return context.json({ token: workflow.sessionToken });
73:       const host = context.req.header("host") ?? "";
74:       if (!host.startsWith("127.0.0.1") && !host.startsWith("localhost")) {
75:         return context.json({ code: "INVALID_ORIGIN", message: "The local session token is only available on loopback.", retryable: false }, 403);
76:       }
77:       return context.json({ token: workflow.sessionToken });
78:     });
79:     if (workflow.experience) {
80:       app.get("/api/export", async (context) => context.json(await workflow.experience!.exportApproved()));
81:     }
82: 
83:     app.use("/api/sections/*", async (context, next) => guard(context, next, workflow.sessionToken));
84:     app.use("/api/messages", async (context, next) => guard(context, next, workflow.sessionToken));
85:     app.use("/api/approvals", async (context, next) => guard(context, next, workflow.sessionToken));
86:     app.use("/api/runs", async (context, next) => guard(context, next, workflow.sessionToken));
87:     app.use("/api/runs/*", async (context, next) => guard(context, next, workflow.sessionToken));
88: 
89:     app.post("/api/sections/:id/revisions", async (context) => {
90:       try {
91:         const input = revisionSchema.parse(await context.req.json());
92:         const result = await workflow.service.execute(
93:           input.actionId,
94:           input,
95:           input.expectedRevision,
96:           (project) => reviseSection(project, context.req.param("id"), input.content),
97:         );
98:         return context.json(result);
99:       } catch (error) {
100:         if (error instanceof RevisionConflict || error instanceof WorkflowConflict) {
101:           return context.json({ code: "WORKFLOW_CONFLICT", message: error.message }, 409);
102:         }
103:         if (error instanceof z.ZodError) return context.json({ code: "INVALID_REQUEST", message: "Invalid revision request." }, 400);
104:         throw error;
105:       }
106:     });
107: 
108:     app.post("/api/sections/:id/approve", async (context) => {
109:       try {
110:         const input = approvalRequestSchema.parse(await context.req.json());
111:         const result = await workflow.service.execute(
112:           input.actionId,
113:           input,
114:           input.expectedRevision,
115:           (project) => approveSection(project, context.req.param("id"), input.version, input.hash),
116:         );
117:         return context.json(result);
118:       } catch (error) {
119:         if (error instanceof RevisionConflict || error instanceof WorkflowConflict) {
120:           return context.json({ code: "WORKFLOW_CONFLICT", message: error.message }, 409);
121:         }
122:         if (error instanceof z.ZodError) return context.json({ code: "INVALID_REQUEST", message: "Invalid approval request.", retryable: true }, 400);
123:         throw error;
124:       }
125:     });
126: 
127:     app.post("/api/messages", async (context) => {
128:       if (!workflow.experience) return unavailable(context);
129:       try {
130:         const input = messageSchema.parse(await context.req.json());
131:         const result = await workflow.experience.sendMessage(input.actionId, input.expectedRevision, input.intent, input.text);
132:         return context.json(result);
133:       } catch (error) {
134:         return journeyError(context, error, "Invalid message.");
135:       }
136:     });
137: 
138:     app.post("/api/approvals", async (context) => {
139:       if (!workflow.experience) return unavailable(context);
140:       try {
141:         const input = approvalKindSchema.parse(await context.req.json());
142:         const statement = input.kind === "maker-scope" ? input.statement : undefined;
143:         const result = await workflow.experience.approve(input.actionId, input.expectedRevision, input.kind, statement);
144:         return context.json(result);
145:       } catch (error) {
146:         return journeyError(context, error, "Invalid approval.");
147:       }
148:     });
149: 
150:     app.post("/api/runs", async (context) => {
151:       if (!workflow.experience) return unavailable(context);
152:       try {
153:         const input = actionSchema.parse(await context.req.json());
154:         const result = await workflow.experience.runMaker(input.actionId, input.expectedRevision);
155:         return context.json(result);
156:       } catch (error) {
157:         return journeyError(context, error, "Invalid Maker run.");
158:       }
159:     });
160: 
161:     app.post("/api/runs/:id/cancel", async (context) => {
162:       if (!workflow.experience) return unavailable(context);
163:       try {
164:         const input = actionSchema.parse(await context.req.json());
165:         const result = await workflow.experience.cancel(input.actionId, input.expectedRevision, context.req.param("id"));
166:         return context.json(result);
167:       } catch (error) {
168:         return journeyError(context, error, "Invalid cancellation.");
169:       }
170:     });
171: 
172:     app.post("/api/runs/:id/reconcile", async (context) => {
173:       if (!workflow.experience) return unavailable(context);
174:       try {
175:         const input = actionSchema.parse(await context.req.json());
176:         const result = await workflow.experience.reconcile(input.actionId, input.expectedRevision, context.req.param("id"));
177:         return context.json(result);
178:       } catch (error) {
179:         return journeyError(context, error, "Invalid reconciliation.");
180:       }
181:     });
182:   }
183: 
184:   return app;
185: }
186: 
187: async function guard(context: Parameters<Parameters<Hono["use"]>[1]>[0], next: () => Promise<void>, sessionToken: string) {
188:   if (context.req.method === "GET") return next();
189:   if (context.req.header("x-ub-session-token") !== sessionToken) {
190:     return context.json({ code: "INVALID_SESSION", message: "Missing or invalid local browser session token.", retryable: false }, 403);
191:   }
192:   return next();
193: }
194: 
195: function unavailable(context: { json: (body: unknown, status?: number) => Response }) {
196:   return context.json({ code: "ENGINE_UNAVAILABLE", message: "The workshop journey is not configured.", retryable: false }, 503);
197: }
198: 
199: function journeyError(context: { json: (body: unknown, status?: number) => Response }, error: unknown, validationMessage: string) {
200:   if (error instanceof ExperienceFailure) {
201:     return context.json({
202:       code: error.code,
203:       message: error.message,
204:       retryable: error.retryable,
205:       operationId: error.operationId,
206:     }, error.status as 400);
207:   }
208:   if (error instanceof RevisionConflict || error instanceof WorkflowConflict) {
209:     return context.json({ code: "WORKFLOW_CONFLICT", message: error.message, retryable: false }, 409);
210:   }
211:   if (error instanceof z.ZodError) return context.json({ code: "INVALID_REQUEST", message: validationMessage, retryable: true }, 400);
212:   throw error;
213: }

