import { contentHash, createProject, projectSchema, type Project } from "../workflow/model.ts";

export const DEMO_WORKSPACE = "demo://read-only";

export interface DemoExport {
  plan: string | null;
  unresolved: string[];
  drafts: Array<{ title: string; content: string }>;
  limitation: string;
}

/**
 * Deterministic, in-memory sample for the public demo. It must never read a
 * repository, start OpenCode, or persist user-specific state.
 */
export function createDemoProject(): Project {
  const base = createProject(DEMO_WORKSPACE);
  const control = base.sections[0];
  control.content = [
    "## Demo scope",
    "",
    "A campus lost-and-found board that lets a student post a found item, claim an item with a short description, and see when the item was returned.",
    "",
    "The public demo is a fixed sample. It does not connect to a repository, OpenCode, a model provider, or any secret.",
  ].join("\n");
  control.version = 1;
  control.hash = contentHash(control.content);
  control.status = "APPROVED";

  const architecture = base.sections[1];
  architecture.content = [
    "## Demo architecture",
    "",
    "A dependency-free Node module stores items in memory, and a node:test suite checks posting, claiming, and duplicate claims.",
    "",
    "This section is shown as a draft so visitors can see the review surface. Approval and revision controls remain disabled in the demo.",
  ].join("\n");
  architecture.version = 1;
  architecture.hash = contentHash(architecture.content);
  architecture.status = "DRAFT";

  return projectSchema.parse({
    ...base,
    id: "demo-project",
    revision: 0,
    stage: "ARCHITECT",
    currentSectionId: architecture.id,
    sections: base.sections,
    approvals: [{
      id: "demo-approval-control",
      sectionId: control.id,
      version: control.version,
      hash: control.hash,
      approvedAt: "2026-10-31T00:00:00.000Z",
      staleReason: null,
    }],
    product: {
      status: "APPROVED",
      proposal: "Build a small campus lost-and-found board with a clear claim flow and a behavioural test.",
      openQuestions: [],
    },
    transcript: [{
      id: "demo-notice",
      spirit: "system",
      text: "Deterministic public demo. No repository, OpenCode session, provider key, or user-specific state is connected.",
      createdAt: "2026-10-31T00:00:00.000Z",
    }],
    nextAction: "Explore the deterministic sample. Mutations are disabled in the public demo.",
  });
}

export function createDemoExport(): DemoExport {
  return {
    plan: null,
    unresolved: ["architecture", "experience", "tools", "verification", "phases", "delivery", "readiness"],
    drafts: [],
    limitation: "Deterministic public demo data. No repository, OpenCode run, provider call, or secret is connected.",
  };
}

