(project) => {
  const next = { ...project, workspace };
  if (project.workspace !== workspace) {
    if (project.evidence.length) {
      next.evidence = project.evidence.map((item) => ({
        ...item,
        result: "STALE" as const,
        limitation: "The workspace changed after this check was observed. Re-run the approved Maker unit in the selected workspace.",
      }));
      next.capabilities = project.capabilities.map((item) => ({ ...item, observedOutcome: null }));
    }
    if (project.operations.some((item) => item.kind === "maker")) {
      next.stage = "MAKER";
      next.nextAction = "Run the approved Maker unit in the selected workspace";
    }
  }
  return next;
},

