test("the rendered capability summary reports repository, OpenCode, storage, and providers", () => {
  const summary = renderToStaticMarkup(createElement(ModeCapabilitySummary, { runtime: local }));
  assert.match(summary, /Repository: selected local/);
  assert.match(summary, /OpenCode: live/);
  assert.match(summary, /Storage: local disk/);
  assert.match(summary, /Providers: OpenCode/);

  const demoSummary = renderToStaticMarkup(createElement(ModeCapabilitySummary, { runtime: demo }));
  assert.match(demoSummary, /Repository: none/);
  assert.match(demoSummary, /OpenCode: off/);
  assert.match(demoSummary, /Storage: none/);
  assert.match(demoSummary, /Providers: off/);

  const hostedSummary = renderToStaticMarkup(createElement(ModeCapabilitySummary, { runtime: hosted }));
  assert.match(hostedSummary, /Repository: managed server/);
  assert.match(hostedSummary, /OpenCode: live/);
  assert.match(hostedSummary, /Storage: private disk/);
  assert.match(hostedSummary, /Providers: Render secrets/);
});

