const fs=require('fs');const path=require('path');
const dir='docs';let missing=[];
for(const f of fs.readdirSync(dir).filter(f=>f.endsWith('.md'))){
 const p=path.join(dir,f);const text=fs.readFileSync(p,'utf8');
 for(const m of text.matchAll(/\]\(([^)#]+)(?:#[^)]*)?\)/g)){
  const target=m[1];if(/^https?:|^mailto:/.test(target))continue;
  const resolved=path.resolve(dir,decodeURI(target));
  if(!fs.existsSync(resolved))missing.push(`${p} -> ${target}`);
 }
}
if(missing.length){console.log(missing.join('\n'));process.exitCode=1}else console.log('all local doc links resolve');
